1	/**
2	 * The MHPCO price list: the office's catalogue of what it will insure and what
3	 * each kind of thing costs. It answers the questions of item *kind* -- is this a
4	 * main item or a component, what is its tariff row -- and nothing about
5	 * underwriting policy or settlement. A new item type revises this table alone.
6	 */
7	
8	export interface Item {
9	  type: string;
10	  material?: string;
11	  enchantment?: number;
12	  cursed?: boolean;
13	}
14	
15	/**
16	 * The price list prices each main item type by its own tariff row, but prices
17	 * every component by one rule: 25 G per component, whatever its kind.
18	 */
19	const MAIN_ITEM_BASE_PREMIUM: Record<string, number> = {
20	  sword: 100,
21	  amulet: 60,
22	  staff: 80,
23	  potion: 40,
24	};
25	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
26	
27	export const COMPONENT_BASE_PREMIUM = 25;
28	
29	export function isComponent(type: string): boolean {
30	  return COMPONENT_TYPES.has(type);
31	}
32	
33	/**
34	 * The tariff row a main item is priced from. Components have no row of their own.
35	 * The MHPCO insures nothing that is absent from its price list, so an unlisted
36	 * type is refused rather than priced.
37	 */
38	export function mainItemBasePremium(type: string): number {
39	  const basePremium = MAIN_ITEM_BASE_PREMIUM[type];
40	  if (basePremium === undefined) {
41	    throw new Error(`The MHPCO does not insure items of type "${type}"`);
42	  }
43	  return basePremium;
44	}
