/**
 * The MHPCO reads risk off main items only. A component is a raw ingredient: it
 * bears no curse and no enchantment of its own, and inside a block it has no
 * premium of its own that a surcharge could be charged against.
 */
function bearsOwnRisk(item: Item): boolean {
  return !isComponent(item.type);
}

/**
 * An item's own risk surcharges are charged on its price-list row, never on the
 * policy total.
 */
function itemRiskSurcharge(item: Item): number {
  if (!bearsOwnRisk(item)) {
    return 0;
  }
  return percentOf(mainItemBasePremium(item.type), itemRiskSurchargePercent(item));
}

function itemSurcharges(items: Item[]): number {
  return items.reduce((total, item) => total + itemRiskSurcharge(item), 0);
}

